package app.kinnect.audit;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import java.lang.reflect.*;import java.nio.*;import java.io.*;import java.util.concurrent.atomic.*;import org.json.*;
/** Two real local WebRTC peers: muted microphone + generated WAV must reach receiver PCM. */
public class KaraokeRtcAudit extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 Object get(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}void set(Object o,String n,Object v)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}Object call(Object o,String n,Class<?>[] ts,Object...a)throws Exception{Method m=o.getClass().getDeclaredMethod(n,ts);m.setAccessible(true);return m.invoke(o,a);}
 void tone(File f)throws Exception{int count=48000*8;ByteBuffer b=ByteBuffer.allocate(44+count*2).order(ByteOrder.LITTLE_ENDIAN);b.put("RIFF".getBytes("US-ASCII")).putInt(36+count*2).put("WAVEfmt ".getBytes("US-ASCII")).putInt(16).putShort((short)1).putShort((short)1).putInt(48000).putInt(96000).putShort((short)2).putShort((short)16).put("data".getBytes("US-ASCII")).putInt(count*2);for(int i=0;i<count;i++)b.putShort((short)(Math.sin(i*2*Math.PI*440/48000)*12000));try(FileOutputStream out=new FileOutputStream(f)){out.write(b.array());}}
 public void onStart(){Bundle out=new Bundle();Object[] peers=new Object[2];File wav=new File(getTargetContext().getCacheDir(),"karaoke-rtc-tone.wav");try{ClassLoader cl=getTargetContext().getClassLoader();Class<?> rtc=cl.loadClass("app.kinnect.live.NativeRtc"),events=cl.loadClass("app.kinnect.live.NativeRtc$Events"),surface=cl.loadClass("org.webrtc.SurfaceViewRenderer");Constructor<?> ctor=rtc.getDeclaredConstructor(Context.class,JSONObject.class,surface,surface,events,boolean.class);ctor.setAccessible(true);AtomicReference<Throwable> failure=new AtomicReference<>();AtomicInteger connections=new AtomicInteger();
  runOnMainSync(()->{try{for(int i=0;i<2;i++){final int index=i;Object listener=Proxy.newProxyInstance(cl,new Class[]{events},(p,m,args)->{try{if(m.getName().equals("signal")){call(peers[1-index],"signal",new Class[]{String.class,JSONObject.class},index==0?"sender":"receiver",args[1]);}if(m.getName().equals("connection")&&(args[0].equals("CONNECTED")||args[0].equals("COMPLETED")))connections.incrementAndGet();}catch(Throwable e){failure.set(e);}return null;});peers[i]=ctor.newInstance(getTargetContext(),new JSONObject().put("iceServers",new JSONArray()),null,null,listener,true);}call(peers[0],"media",new Class[]{Context.class,boolean.class},getTargetContext(),false);call(peers[0],"microphone",new Class[]{boolean.class},false);}catch(Throwable e){failure.set(e);}});if(failure.get()!=null)throw new AssertionError(failure.get());
  Object mix=call(peers[0],"audioMix",new Class[]{});tone(wav);call(mix,"load",new Class[]{Context.class,Uri.class},getTargetContext(),Uri.fromFile(wav));AtomicLong energy=new AtomicLong(),samples=new AtomicLong();Class<?> callback=cl.loadClass("org.webrtc.audio.JavaAudioDeviceModule$PlaybackSamplesReadyCallback");Object receiverOutput=get(get(peers[1],"mixModule"),"audioOutput");set(receiverOutput,"audioSamplesReadyCallback",Proxy.newProxyInstance(cl,new Class[]{callback},(p,m,args)->{if(args!=null&&args.length>0){byte[] pcm=(byte[])args[0].getClass().getMethod("getData").invoke(args[0]);long sum=0;for(int i=0;i+1<pcm.length;i+=2)sum+=Math.abs((short)((pcm[i]&255)|(pcm[i+1]<<8)));energy.addAndGet(sum);samples.addAndGet(pcm.length/2);}return null;}));
  runOnMainSync(()->{try{call(peers[0],"offer",new Class[]{String.class},"receiver");}catch(Throwable e){failure.set(e);}});for(int i=0;i<100&&connections.get()<2&&failure.get()==null;i++)Thread.sleep(100);if(connections.get()<2||failure.get()!=null)throw new AssertionError("Local WebRTC failed: "+failure.get());Thread.sleep(500);energy.set(0);samples.set(0);set(mix,"playing",true);Thread.sleep(2200);long n=samples.get(),mean=n==0?0:energy.get()/n;if(n<10000||mean<700)throw new AssertionError("Receiver music missing: samples="+n+", energy="+mean);if((Boolean)get(mix,"mic"))throw new AssertionError("Microphone must remain muted");long position=(Long)call(mix,"positionMs",new Class[]{});if(position<1000)throw new AssertionError("No encoding audio clock");out.putString("result","PASS: two actual local WebRTC peers connected; muted microphone remained muted; generated WAV traversed mixer, Opus encode/decode and receiver PCM (mean amplitude "+mean+", "+n+" samples). No server or personal audio.");
  runOnMainSync(()->{for(Object p:peers)if(p!=null)try{call(p,"close",new Class[]{});}catch(Exception ignored){}});wav.delete();finish(Activity.RESULT_OK,out);
 }catch(Throwable e){runOnMainSync(()->{for(Object p:peers)if(p!=null)try{call(p,"close",new Class[]{});}catch(Exception ignored){}});wav.delete();out.putString("error",e.toString());finish(Activity.RESULT_CANCELED,out);}}
}
